async function renderTasks(projectId) {
  app.insertAdjacentHTML('beforeend', '<form id="task-form"><label for="task-title">Task title</label><div class="controls"><input id="task-title" type="text"><button type="submit" disabled>Create task</button></div><p role="alert" hidden></p></form><div class="filter"><label for="task-filter">Task filter</label><select id="task-filter"><option>All</option><option>Open</option><option>Completed</option></select></div><section id="tasks" aria-label="Tasks"></section>');
  const endpoint = '/api/projects/' + projectId + '/tasks';
  const form = document.getElementById('task-form');
  const input = document.getElementById('task-title');
  const button = form.querySelector('button');
  const filter = document.getElementById('task-filter');
  const list = document.getElementById('tasks');
  let tasks = await request(endpoint);
  function drawTasks() {
    list.replaceChildren();
    for (const task of tasks) {
      if (filter.value === 'Open' && task.completed) continue;
      if (filter.value === 'Completed' && !task.completed) continue;
      const row = document.createElement('div');
      row.className = 'task-row';
      row.dataset.testid = 'task-row';
      const checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.checked = task.completed;
      checkbox.setAttribute('aria-label', 'Complete ' + task.title);
      const title = document.createElement('span');
      title.textContent = task.title;
      checkbox.addEventListener('change', async () => {
        checkbox.disabled = true;
        app.querySelector('[role="alert"]').hidden = true;
        try {
          const updated = await request(endpoint + '/' + task.id, {
            method: 'PATCH', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ completed: checkbox.checked })
          });
          Object.assign(task, updated);
          drawTasks();
        } catch (error) {
          checkbox.checked = task.completed;
          showError(error.message);
        } finally { checkbox.disabled = false; }
      });
      row.append(checkbox, title);
      list.append(row);
    }
  }
  drawTasks();
  button.disabled = false;
  filter.addEventListener('change', drawTasks);
  form.addEventListener('submit', async event => {
    event.preventDefault();
    const title = input.value.trim();
    if (!title) { showError('Task title is required'); return; }
    button.disabled = true;
    app.querySelector('[role="alert"]').hidden = true;
    try {
      tasks.push(await request(endpoint, {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title })
      }));
      drawTasks();
      input.value = '';
      input.focus();
    } catch (error) { showError(error.message); }
    finally { button.disabled = false; }
  });
}
